window.seaProfitRow = (db, sh) => {
  const n = x => +x || 0;
  const c = (db.seaCosts || {})[sh.code] || {};
  const L = db.lines.filter(l => l.shipment === sh.code);
  const cbm = +L.reduce((a, l) => a + n(l.actual ?? l.measure), 0).toFixed(2);
  const ld = +L.reduce((a, l) => a + n(l.delivery), 0).toFixed(2),
    ic = +L.reduce((a, l) => a + n(l.fatura), 0).toFixed(2);
  const A = (db.arrCosts || {})[sh.code] || {};
  const tax = n(A.canshur) + n(A.xalin);
  const port = +(SEA_ROWS.reduce((a, [k]) => a + n(A[k]), 0) - tax).toFixed(2);
  const trCost = +(n(c.custom) + n(c.freight) + n(c.ltrans) + ld + ic + n(c.storage) + n(c.brand)).toFixed(2);
  const totCost = +(trCost + port + tax).toFixed(2);
  const nos = new Set(db.invoices.filter(i => i.shipment === sh.code).map(i => i.no));
  const coll = +db.payments.filter(p => nos.has(p.inv)).reduce((a, p) => a + n(p.amount), 0).toFixed(2);
  const com = window.commissionOf ? window.commissionOf(db, sh.code) : 0;
  const incSo = +(coll - com - n(c.transfer)).toFixed(2),
    incTr = n(c.incomeTr);
  const totInc = +(incSo + incTr + n(c.brandIncSo) + n(c.brandIncTr)).toFixed(2);
  return {
    c,
    cbm,
    ld,
    ic,
    port,
    tax,
    trCost,
    totCost,
    coll,
    com,
    incSo,
    incTr,
    totInc,
    profit: +(totInc - totCost).toFixed(2)
  };
};
